mapper.insert:
INSERT INTO pjt_approval_documents (
    doc_no, title, content, status, current_step, version, drafter_id, file_group_id,
    submitted_at, completed_at, created_at, updated_at
) VALUES (
    #{docNo}, #{title}, #{content}, #{status}, #{currentStep}, #{version}, #{drafterId}, #{fileGroupId},
    #{submittedAt}, #{completedAt}, #{createdAt}, #{updatedAt}
)

choose.when:
AND id IN (
    SELECT document_id FROM pjt_approval_lines
    WHERE approver_id = #{viewerId}
      AND status = 'PENDING'
      AND line_type IN ('APPROVE', 'AGREE', 'POST')
      AND (
        (line_type IN ('APPROVE', 'AGREE') AND active = TRUE)
        OR line_type = 'POST'
      )
)

choose.otherwise:
AND (
    drafter_id = #{viewerId}
    OR id IN (SELECT document_id FROM pjt_approval_lines WHERE approver_id = #{viewerId})
)

mapper.select:
SELECT * FROM pjt_approval_documents

ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
